mapper.select:
SELECT id, tenant_id, actor, action, target,
       CAST(before_state AS VARCHAR) AS before_state,
       CAST(after_state AS VARCHAR) AS after_state,
       trace_id, created_at
FROM audit_logs
WHERE 1 = 1

    AND tenant_id = #{tenantId,jdbcType=VARCHAR}


    AND action = #{action,jdbcType=VARCHAR}


    AND target LIKE CONCAT('%', #{target,jdbcType=VARCHAR}, '%')


    AND created_at >= #{from,jdbcType=TIMESTAMP}


    AND created_at <= #{to,jdbcType=TIMESTAMP}

ORDER BY id DESC
LIMIT #{limit,jdbcType=INTEGER} OFFSET #{offset,jdbcType=INTEGER}
